{
  "sql": "SELECT t1.product_category_name_english AS categoria, AVG(t2.review_score) AS calificacion_promedio, AVG(CASE WHEN t4.dias_retraso > 0 THEN 1 ELSE 0 END) AS pct_retrasos FROM product_category_translation t1 LEFT JOIN products t2 ON t1.product_category_name = t2.product_category_name LEFT JOIN order_reviews t3 ON t3.order_id = t2.product_id LEFT JOIN vw_entregas_retrasos t4 ON t3.order_id = t4.order_id WHERE t2.product_id IS NOT NULL GROUP BY t1.product_category_name_english HAVING COUNT(t3.review_id) >= 100 AND AVG(t2.review_score) < ( SELECT AVG(review_score) FROM order_reviews ) AND AVG(CASE WHEN t4.dias_retraso > 0 THEN 1 ELSE 0 END) < ( SELECT AVG(CASE WHEN t4.dias_retraso > 0 THEN 1 ELSE 0 END) FROM vw_entregas_retrasos )"
}
